/usr/bin/bash -lc "python - <<'PY'
from bs4 import BeautifulSoup
from pathlib import Path
from openpyxl import load_workbook
import re

html=Path('raw_filing/petsmart_2015-02-02_DEFM14A.htm').read_text(errors='ignore')
s=BeautifulSoup(html,'lxml')
pages={}
for div in s.find_all('div',style=lambda x:x and 'page-break-after:always' in x):
    nums=[x.get_text(' ',strip=True) for x in div.find_all('div')[-8:] if x.get_text(' ',strip=True).isdigit()]
    if nums:
        pages[int(nums[-1])]=div.get_text(' ',strip=True)

def norm(x):
    return re.sub(r'\\s+',' ',x.replace('\\xa0',' ')).strip()

wb=load_workbook('extraction/petsmart.xlsx',data_only=False)
ws=wb['Deal ledger']
issues=[]
valid_types={'Strategic','Financial','Mixed','Unknown',None}
valid_events={'Target interest','Bidder interest','Target sale decision','Activist','Adviser','Adviser ended','Contact','NDA signed','Round opened','Deadline set','Deadline revised','Deadline','Exclusivity changed','Other material event','Bid','Bid reaffirmed','Other-scope bid','Bidding group changed','Dropped by target','Withdrew','Did not submit','Not selected at signing','Re-entered','Sale process announced','Bid announced','Merger announced','Merger agreement signed','Go-shop changed','Process terminated','Process restarted'}
valid_cash={'Yes','No','Not stated',None}
valid_form={'Formal','Informal','Unclear',None}
valid_cond={'None','Light','Heavy','Unclear',None}
valid_exit={'Value below market price','Value at or below market price','Value below earlier offer','Value at earlier offer','Would not improve earlier offer','Lower offer than rivals','Terms or process','Other stated reason','Not stated',None}
for r in range(2,ws.max_row+1):
    num=ws.cell(r,1).value
    vals=[ws.cell(r,c).value for c in range(1,23)]
    if vals[3] not in valid_types: issues.append((num,'type',vals[3]))
    if vals[4] not in valid_events: issues.append((num,'event',vals[4]))
    if vals[9] not in valid_cash: issues.append((num,'cash',vals[9]))
    if vals[10] not in valid_form: issues.append((num,'form',vals[10]))
    if vals[11] not in valid_cond: issues.append((num,'cond',vals[11]))
    if vals[13] not in valid_exit: issues.append((num,'exit',vals[13]))
    event=vals[4]
    if event in {'Bid','Bid reaffirmed','Other-scope bid'}:
        if vals[9] is None or vals[10] is None or vals[11] is None: issues.append((num,'missing bid controlled',vals[9:12]))
    elif any(vals[i] is not None for i in [7,8,9,10,11]):
        issues.append((num,'bid fields outside bid',vals[7:12]))
    if event in {'Dropped by target','Withdrew','Did not submit','Not selected at signing'}:
        if vals[13] is None: issues.append((num,'missing exit reason'))
    elif vals[13] is not None:
        issues.append((num,'exit reason outside exit'))
    q=vals[16]
    m=re.search(r'\\(p\\. (\\d+)\\)"'$'"',q or '')
    if not m:
        issues.append((num,'bad page format',q))
    else:
        pg=int(m.group(1))
        quote=q[:m.start()].strip()
        if quote.startswith('“') and quote.endswith('”'):
            quote=quote[1:-1]
        else:
            issues.append((num,'bad curly quotes',q))
        if norm(quote) not in norm(pages.get(pg,'')):
            issues.append((num,'quote not exact',pg,quote))
print('sheets',wb.sheetnames)
print('ledger_rows',ws.max_row-1,'issues',len(issues))
for x in issues: print(x)
print('size',Path('extraction/petsmart.xlsx').stat().st_size)
PY"

